#include "native/providers/gdn/sm121_q1_math.h"
#include <algorithm>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <stdexcept>
#include <vector>

using namespace qrt_sm121_q1;
template <class T> std::vector<T> read(const char* path) {
    std::ifstream f(path, std::ios::binary | std::ios::ate);
    if (!f || f.tellg() < 0 || size_t(f.tellg()) > (256u << 20) || size_t(f.tellg()) % sizeof(T))
        throw std::runtime_error(path);
    std::vector<T> data(size_t(f.tellg()) / sizeof(T));
    f.seekg(0); f.read(reinterpret_cast<char*>(data.data()), data.size() * sizeof(T));
    if (!f) throw std::runtime_error(path);
    return data;
}
template <class T> void write(const char* path, const std::vector<T>& data) {
    std::ofstream f(path, std::ios::binary);
    f.write(reinterpret_cast<const char*>(data.data()), data.size() * sizeof(T));
    if (!f) throw std::runtime_error(path);
}
int main(int argc, char** argv) try {
    if (argc != 16) throw std::runtime_error("conv a b before after core gtable beta exp2 rsqrt actual-state actual-core sqrt reciprocal packed-mode");
    auto conv_b = read<uint16_t>(argv[1]), a = read<uint16_t>(argv[2]), b = read<uint16_t>(argv[3]);
    auto before = read<float>(argv[4]), after = read<float>(argv[5]);
    auto expected_core = read<uint16_t>(argv[6]);
    auto gt = read<float>(argv[7]), bt = read<float>(argv[8]);
    auto exp2 = read<unsigned char>(argv[9]), rsqrt = read<unsigned char>(argv[10]);
    if (conv_b.size() != 8192 || a.size() != 32 || b.size() != 32 || before.size() != 524288 ||
        after.size() != 524288 || expected_core.size() != 4096 || gt.size() != 2097152 || bt.size() != 65536 ||
        !qrt_sm121_exp2::valid_layout(exp2.data(), exp2.size()) ||
        !qrt_sm121_rsqrt::valid_layout(rsqrt.data(), rsqrt.size())) throw std::runtime_error("shapes/table layout");
    auto sqrt_table=read<unsigned char>(argv[13]), reciprocal=read<unsigned char>(argv[14]);
    if (!qrt_sm121_sqrt::valid_layout(sqrt_table.data(),sqrt_table.size()) || !qrt_sm121_attention_rcp::valid_layout(reciprocal.data(),reciprocal.size())) throw std::runtime_error("packed table layout");
    const std::string mode=argv[15]; if (mode!="0" && mode!="1") throw std::runtime_error("packed mode"); const bool packed=mode=="1";
    std::vector<float> conv(8192), output(before.size());
    std::vector<uint16_t> core(4096);
    for (unsigned i = 0; i < conv.size(); ++i) conv[i] = widen(conv_b[i]);
    unsigned state_bad = 0, core_bad = 0, first_state = 524288, first_core = 4096;
    unsigned state_by_head[32] = {}, core_by_head[32] = {};
    double maximum_state_error = 0;
    for (unsigned h = 0; h < 32; ++h) {
        float q[128], k[128];
        const float qi = (packed ? packed_inverse_norm(conv.data() + (h / 2) * 128, sqrt_table.data(), reciprocal.data()) : inverse_norm(conv.data() + (h / 2) * 128, rsqrt.data()));
        const float ki = (packed ? packed_inverse_norm(conv.data() + 2048 + (h / 2) * 128, sqrt_table.data(), reciprocal.data()) : inverse_norm(conv.data() + 2048 + (h / 2) * 128, rsqrt.data()));
        for (unsigned i = 0; i < 128; ++i) {
            q[i] = multiply(multiply(conv[(h / 2) * 128 + i], qi), 0x1.6a09e6p-4f);
            k[i] = multiply(conv[2048 + (h / 2) * 128 + i], ki);
        }
        const float g = gt[h * 65536u + a[h]], beta = packed ? widen(bf16(bt[b[h]])) : bt[b[h]];
        const float decay = qrt_sm121_exp2::evaluate(exp2.data(), multiply(g, 0x1.715476p+0f));
        for (unsigned v = 0; v < 128; ++v) {
            const unsigned offset = (h * 128 + v) * 128; // Original capture: [head][value][key].
            float row[128];
            for (unsigned i = 0; i < 128; ++i) row[i] = before[offset + i];
            const float projected = state_dot(row, 1, decay, k, v, true, packed);
            const float residual = multiply(add(conv[4096 + h * 128 + v], -projected), beta);
            for (unsigned i = 0; i < 128; ++i) {
                row[i] = fmaf(residual, k[i], multiply(row[i], decay));
                const unsigned at = offset + i;
                output[at] = row[i];
                if (!std::isfinite(row[i]) || !std::isfinite(after[at])) throw std::runtime_error("nonfinite state");
                maximum_state_error = std::max(maximum_state_error, std::abs(double(row[i]) - after[at]));
                if (qrt_sm121_exp2::bits(row[i]) != qrt_sm121_exp2::bits(after[at])) {
                    ++state_bad; ++state_by_head[h]; first_state = std::min(first_state, at);
                }
            }
            const unsigned at = h * 128 + v;
            core[at] = bf16(state_dot(row, 1, 1.f, q, v, false));
            if (!std::isfinite(widen(core[at])) || !std::isfinite(widen(expected_core[at]))) throw std::runtime_error("nonfinite core");
            if (core[at] != expected_core[at]) { ++core_bad; ++core_by_head[h]; first_core = std::min(first_core, at); }
        }
    }
    write(argv[11], output); write(argv[12], core);
    std::cout << std::setprecision(17) << "{\"state_f32_bit_mismatches\":" << state_bad
        << ",\"core_bf16_mismatches\":" << core_bad << ",\"maximum_state_absolute_error\":" << maximum_state_error;
    std::cout << ",\"first_state_difference\":";
    if (state_bad) std::cout << "{\"index\":" << first_state << ",\"actual_bits\":" << qrt_sm121_exp2::bits(output[first_state])
        << ",\"expected_bits\":" << qrt_sm121_exp2::bits(after[first_state]) << "}";
    else std::cout << "null";
    std::cout << ",\"first_core_difference\":";
    if (core_bad) std::cout << "{\"index\":" << first_core << ",\"actual_bits\":" << core[first_core]
        << ",\"expected_bits\":" << expected_core[first_core] << "}";
    else std::cout << "null";
    std::cout << ",\"state_mismatches_by_head\":[";
    for (unsigned h = 0; h < 32; ++h) std::cout << (h ? "," : "") << state_by_head[h];
    std::cout << "],\"core_mismatches_by_head\":[";
    for (unsigned h = 0; h < 32; ++h) std::cout << (h ? "," : "") << core_by_head[h];
    std::cout << "]}\n";
} catch (const std::exception& e) { std::cerr << e.what() << '\n'; return 2; }
